"""field_map_review.py — regenerates data/field_maps/REVIEW.md (human review sheet) from the map JSON files."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main():
    man = {d["doc_id"]: d for d in json.loads((ROOT / "data" / "manifest.json").read_text(encoding="utf-8"))["documents"]}
    lines = ["# Field map review sheet", "",
             "Generated by `scripts/field_map_review.py`. For each report, check the page ranges against the PDF's table of",
             "contents and fix wrong ranges **in the JSON file**, then set `\"status\": \"reviewed\"` and `\"reviewed_by\"`.",
             "Ranges marked **REVIEW** are judgement calls. Review before labelling the field test sheet.", "",
             "Fields: `description`, `analysis`, `recommendations`, `other`. First matching range wins; `section_regex`",
             "limits a range to passages whose section heading matches.", ""]
    n_review = 0
    for f in sorted((ROOT / "data" / "field_maps").glob("*.json")):
        m = json.loads(f.read_text(encoding="utf-8")); d = man[m["doc_id"]]
        lines += [f"## {d['title']}", "", f"`{f.name}` · {d['pages']} pages · status **{m['status']}** · default `{m['default']}`", "",
                  "| # | Pages | Field | Applies to | Section filter |", "|---|---|---|---|---|"]
        for i, r in enumerate(m["ranges"]):
            lab = r["label"].replace("|", "/").replace(" - REVIEW", " — **REVIEW**")
            n_review += "REVIEW" in r["label"]
            lines.append(f"| {i} | {r['pages'][0]}–{r['pages'][1]} | `{r['field']}` | {lab} | "
                         f"{('`' + r['section_regex'] + '`') if r.get('section_regex') else ''} |")
        lines.append("")
    (ROOT / "data" / "field_maps" / "REVIEW.md").write_text("\n".join(lines), encoding="utf-8")
    print(f"{n_review} REVIEW ranges")
    return 0


if __name__ == "__main__":
    sys.exit(main())
